mapper.sql:
SELECT m.id, m.scene_code, m.title, m.content_type, m.category_id, c.name AS category_name, m.link_url, m.sender_user_id, r.is_read, r.read_time, m.created_at, m.updated_at, m.created_by, m.updated_by FROM in_app_message_recipient r INNER JOIN in_app_message m ON m.id = r.message_id LEFT JOIN in_app_message_category c ON c.id = m.category_id WHERE r.user_id = #{userId} AND r.is_deleted = 0 AND m.recipient_scope_type != 'ALL' AND m.status IN ('SUCCESS', 'PARTIAL')
AND r.is_read = #{query.isRead}
AND c.parent_id = #{query.majorCategoryId}
AND m.category_id = #{query.categoryId}
AND m.title LIKE CONCAT(#{query.title}, '%')

SELECT m.id, m.scene_code, m.title, m.content_type, m.category_id, c.name AS category_name, m.link_url, m.sender_user_id, COALESCE(s.is_read, 0) AS is_read, s.read_time, m.created_at, m.updated_at, m.created_by, m.updated_by FROM in_app_message m LEFT JOIN in_app_message_user_status s ON s.message_id = m.id AND s.user_id = #{userId} LEFT JOIN in_app_message_category c ON c.id = m.category_id WHERE m.recipient_scope_type = 'ALL' AND m.status = 'SUCCESS' AND ( s.id IS NULL OR s.is_deleted = 0 )
AND s.is_read = 1
AND ( s.id IS NULL OR s.is_read = 0 )
AND c.parent_id = #{query.majorCategoryId}
AND m.category_id = #{query.categoryId}
AND m.title LIKE CONCAT(#{query.title}, '%')

mapper.select:
SELECT id, scene_code, title, content_type, category_id, category_name, link_url, sender_user_id, is_read, read_time, created_at, updated_at, created_by, updated_by FROM (
UNION ALL
) inbox ORDER BY is_read ASC, created_at DESC
